import{z as o,x as i,o as A,c as s,q as e,j as t,D as a,d as l,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"内核接口的框架对照","description":"","frontmatter":{"title":"内核接口的框架对照","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fw-kernel-interface-comparison.md","filePath":"llm/fw-kernel-interface-comparison.md","lastUpdated":1791063341000}'),C={name:"llm/fw-kernel-interface-comparison.md"};function D(d,E,p,F,h,m){const B=i("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="内核接口的框架对照" tabindex="-1">内核接口的框架对照 <a class="header-anchor" href="#内核接口的框架对照" aria-label="Permalink to &quot;内核接口的框架对照&quot;">​</a></h1><div class="epigraph"><p>调度器的分歧在进程边界，内核接口的分歧在「谁决定用哪个核」：运行期注册、构建期浇死、配置切换、图算子，四条路各有买主。</p><footer>—— 据 Dao 等，FlashAttention，2022；FlashInfer 项目文档与各仓库注意力后端源码整理</footer></div><p><a href="/llm/fw-scheduler-comparison">上一课</a>把调度器并排，本课往下走一层，把注意力后端的接口并排。内核内部已各有课：tiling 与 online softmax 见 <a href="/llm/ak-flashattention-reread">FlashAttention 重读</a>，分页 KV 的核内寻址见 <a href="/llm/ak-paged-kv-kernel">分页 KV 的内核接口</a>，选型与压测方法见 <a href="/llm/ak-benchmark-methodology">内核基准方法论</a>。本课不进核，只看框架给核留的<strong>插座</strong>长什么样，以各仓库当时状态为准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读六家仓库的注意力代码，字段几乎相同——查询、键值、页表或缓存、缩放——但「这行代码会跑哪个核」的决定方式完全不同。同一份权重换一家框架，性能差出一截，往往不是核本身快慢，而是插座设计的自由度不同：有的运行期按批形状挑核，有的构建期一次定死，有的让调用方字符串切换，有的把注意力降成图上的一个算子。走读要回答：插座怎么设计，决定了换核的成本由谁在何时付。</p><p><span class="marginnote">术语翻译：「核」（kernel）是跑在 GPU 上的最小编译单元，比如「做一次注意力计算」的那个函数；「插座」是框架留给核的接口位置。同一台机器上往往装着好几个注意力核（朴素版、FlashAttention 版、分页版），「插座」决定这次调用接哪个核、以及换核要动多少代码。</span></p><h3 id="四条路线" tabindex="-1">四条路线 <a class="header-anchor" href="#四条路线" aria-label="Permalink to &quot;四条路线&quot;">​</a></h3><p>运行期注册是服务引擎的路线：vLLM 与 SGLang 都有后端注册表，注意力层只是个门面，初始化时按平台与配置选好后端，每步前向把批的元数据装成该后端认识的描述对象——vLLM 的后端基类与每后端的元数据类、SGLang 的前向模式枚举都是「元数据即接口」的实例，换核不改模型代码，代价是每步要为描述对象付搬运。构建期定死是编译路线：TensorRT-LLM 在引擎计划里选定上下文与生成阶段各自的核，MLC 靠调度模板加代码生成、必要时外包给现成注意力库，运行期零分派，代价是重编。配置切换是最薄的插座：Transformers 用一个实现名在朴素、缩放点积、FlashAttention 实现间切换，研究友好，但没有分页元数据的位置。图算子路线在 llama.cpp：注意力是构建函数压进图的节点，各后端各自实现同一算子，插座就是算子语义本身。</p>',8)),(A(),t(r,null,{default:a(()=>[n(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LYR%5B%22%E6%A8%A1%E5%9E%8B%E9%87%8C%E7%9A%84%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%B1%82%EF%BC%88%E9%97%A8%E9%9D%A2%EF%BC%89%22%5D%20--%3E%20A%5B%22%E8%BF%90%E8%A1%8C%E6%9C%9F%E6%B3%A8%E5%86%8C%E8%A1%A8%EF%BC%9A%E5%90%8E%E7%AB%AF%20%2B%20%E5%85%83%E6%95%B0%E6%8D%AE%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20LYR%20--%3E%20B%5B%22%E6%9E%84%E5%BB%BA%E6%9C%9F%E9%80%89%E5%AE%9A%EF%BC%9A%E5%BC%95%E6%93%8E%E8%AE%A1%E5%88%92%20%2F%20%E8%B0%83%E5%BA%A6%E6%A8%A1%E6%9D%BF%22%5D%0A%20%20LYR%20--%3E%20C%5B%22%E9%85%8D%E7%BD%AE%E5%88%87%E6%8D%A2%EF%BC%9A%E5%AE%9E%E7%8E%B0%E5%90%8D%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%0A%20%20LYR%20--%3E%20D%5B%22%E5%9B%BE%E7%AE%97%E5%AD%90%EF%BC%9A%E8%8A%82%E7%82%B9%E8%AF%AD%E4%B9%89%20%2B%20%E5%90%8E%E7%AB%AF%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20A%20--%3E%20K1%5B%22%E6%AF%8F%E6%AD%A5%E5%8F%AF%E6%8D%A2%EF%BC%8C%E4%BB%98%E5%85%83%E6%95%B0%E6%8D%AE%E6%90%AC%E8%BF%90%22%5D%0A%20%20B%20--%3E%20K2%5B%22%E8%BF%90%E8%A1%8C%E6%9C%9F%E9%9B%B6%E5%88%86%E6%B4%BE%EF%BC%8C%E4%BB%98%E9%87%8D%E7%BC%96%22%5D%0A%20%20C%20--%3E%20K3%5B%22%E6%9C%80%E8%96%84%EF%BC%8C%E6%97%A0%E5%88%86%E9%A1%B5%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20D%20--%3E%20K4%5B%22%E8%B7%A8%E8%AE%BE%E5%A4%87%E7%BB%9F%E4%B8%80%EF%BC%8C%E7%B2%92%E5%BA%A6%E7%B2%97%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">分页元数据是分水岭：能接纳「键值散在物理页上」这一信息的插座（服务引擎两家）天然与 PagedAttention 兼容；没有这个位置的插座（实现名字符串）想上分页，就得把整层接口重造——这正是引擎与库的分界线，不只是性能差距。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照的方法沿用三问式，换成插座版：一问决定时机——核的选择发生在装批时、初始化时还是编译时；二问元数据形状——分页信息、前向模式、量化描述放在哪个对象里，谁生产谁消费；三问替换成本——换个核要改一行配置、重跑一次初始化，还是重走一遍构建流水线。给一个新框架对号入座后，就能预测它接新核（比如下一代注意力实现）的阵痛会出现在哪一层：接进注册表，还是要动模型定义，还是要用户重编。</p><p><span class="marginnote">直觉类比四条路线：运行期注册像自助餐，每盘菜现选；配置切换像进门时点套餐，一顿不变；图算子像食堂统一菜单，换食堂才换菜；构建期定死像预制菜——出餐最快，但想换菜得重做一整批。第一个每步都要「想吃什么」（付税），最后一个从不想（零税），换菜最贵。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四条路线的成因回到上一课的同一根轴：<strong>决策放在哪个边界</strong>。运行期注册把决策放在最热的边界上，自由度最大、每步付税；构建期定死把决策推到最冷的边界，热路径零税、但每次变档重付；配置切换把决策交还用户，库方最省、表达力最弱；图算子把决策化进语义，设备可换、粒度最粗。没有一家同时占全四格：服务引擎为了投机解码与混合批，也要在注册表内再做运行期分派；编译路线为了动态形状，也要在计划里留形状桶。插座的最终形态是折中位置的声明，与调度器的进程位置互为镜像。</p>',6)),(A(),t(r,null,{default:a(()=>[n(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20HOT%5B%22%E7%83%AD%E8%BE%B9%E7%95%8C%EF%BC%9A%E6%AF%8F%E6%AD%A5%E5%89%8D%E5%90%91%E6%97%B6%E5%86%B3%E7%AD%96%22%5D%20--%3E%7C%22%E8%87%AA%E7%94%B1%E5%BA%A6%E5%A4%A7%EF%BC%8C%E6%AF%8F%E6%AD%A5%E4%BB%98%E5%88%86%E6%B4%BE%E7%A8%8E%22%7C%20W1%5B%22%E8%BF%90%E8%A1%8C%E6%9C%9F%E6%B3%A8%E5%86%8C%22%5D%0A%20%20W1%20--%3E%20MID%5B%22%E6%B8%A9%E8%BE%B9%E7%95%8C%EF%BC%9A%E5%88%9D%E5%A7%8B%E5%8C%96%2F%E8%A3%85%E6%89%B9%E6%97%B6%E5%86%B3%E7%AD%96%22%5D%0A%20%20MID%20--%3E%20W2%5B%22%E9%85%8D%E7%BD%AE%E5%88%87%E6%8D%A2%22%5D%0A%20%20MID%20--%3E%7C%22%E7%A1%AE%E5%AE%9A%E6%80%A7%E9%AB%98%EF%BC%8C%E5%8F%98%E4%B8%80%E6%AC%A1%E6%A1%A3%E4%BB%A3%E4%BB%B7%E4%B8%AD%22%7C%20W3%5B%22%E5%9B%BE%E7%AE%97%E5%AD%90%22%5D%0A%20%20W3%20--%3E%20COLD%5B%22%E5%86%B7%E8%BE%B9%E7%95%8C%EF%BC%9A%E7%BC%96%E8%AF%91%E6%97%B6%E5%86%B3%E7%AD%96%22%5D%0A%20%20COLD%20--%3E%7C%22%E9%9B%B6%E8%BF%90%E8%A1%8C%E6%9C%9F%E7%A8%8E%EF%BC%8C%E5%8F%98%E6%A1%A3%3D%E9%87%8D%E7%BC%96%22%7C%20W4%5B%22%E6%9E%84%E5%BB%BA%E6%9C%9F%E5%AE%9A%E6%AD%BB%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只对照注意力插座；矩阵乘、归一化、采样的接口各有自己的形状，不并排。核内部的 tiling、寄存器预算与压测不在本课，方法课与重读课已覆盖。对照对象是主流开源仓库，商用闭源栈的插座只能从文档反推，不做结论。类名与注册方式随版本漂移，以仓库当时状态为准；下一课把同一方法用于 KV 的数据结构，那里没有注册表，分歧反而更裸。</p><p><span class="marginnote">常见误区： benchmark 里发现两家框架速度差一截，就断定「某家的核更快」。实际上差距常常出在插座——一边每次前向要组装元数据对象、按形状分派，另一边编译期就焊死了调用。选型时先分清「核的效率」和「接核的税」，再决定要不要为几个百分点重编整条流水线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核插座四路线：运行期注册、构建期定死、配置切换、图算子，由「谁在哪个边界决定用哪个核」区分。</li><li>分页元数据有无是引擎与库的分界：没有它的位置，分页核接不进来。</li><li>决策边界越热自由度越大、每步付税越多；越冷越确定、变档越贵，与调度器位置互为镜像。</li><li>对照三问：决定时机、元数据形状、替换成本；用于预测新框架接新核的阵痛层。</li><li>类名与注册方式随版本漂移，以仓库当时状态为准；出处为 FlashAttention（2022）、FlashInfer 文档与各仓库源码。</li></ul>',5))])}const _=o(C,[["render",D]]);export{f as __pageData,_ as default};
